```javascript
'use strict';

function calculateInvoiceSubtotal(lines) {
  if (!Array.isArray(lines)) throw new TypeError('lines must be an array');
  let total = 0;
  for (const line of lines) {
    if (!line || typeof line !== 'object' || Array.isArray(line)) throw new TypeError('line must be an object');
    if (typeof line.unitPrice !== 'number' || !Number.isFinite(line.unitPrice)) throw new TypeError('unitPrice must be finite');
    if (!Number.isInteger(line.quantity)) throw new TypeError('quantity must be an integer');
    if (line.unitPrice < 0 || line.quantity < 0) throw new RangeError('line values must be non-negative');
    total += line.unitPrice * line.quantity;
  }
  if (!Number.isFinite(total)) throw new RangeError('subtotal is too large');
  return total.toFixed(2);
}

module.exports = { calculateInvoiceSubtotal };
```

