'use strict';

const assert = require('node:assert/strict');
const api = require('./solution');

assert.deepEqual(Object.keys(api), ['calculateInvoiceSubtotal']);
const { calculateInvoiceSubtotal } = api;

assert.throws(() => calculateInvoiceSubtotal(null), TypeError);
assert.throws(() => calculateInvoiceSubtotal({}), TypeError);
assert.strictEqual(calculateInvoiceSubtotal([]), 0);

const lines = [
  { unitPrice: 1.234, quantity: 2 },
  { unitPrice: 10, quantity: 3 },
  { unitPrice: 999, quantity: 0 },
  { unitPrice: 0, quantity: 100 }
];
const copy = lines.map(line => ({ ...line }));
const subtotal = calculateInvoiceSubtotal(lines);
assert.equal(typeof subtotal, 'number');
assert.strictEqual(subtotal, 32.47);
assert.deepEqual(lines, copy);

assert.strictEqual(calculateInvoiceSubtotal([
  { unitPrice: 0.1, quantity: 1 },
  { unitPrice: 0.2, quantity: 1 }
]), 0.3);
assert.strictEqual(calculateInvoiceSubtotal([{ unitPrice: 2.675, quantity: 2 }]), 5.35);

for (const line of [null, undefined, [], 'line', 3]) {
  assert.throws(() => calculateInvoiceSubtotal([line]), TypeError);
}
for (const unitPrice of ['1', null, NaN, Infinity, -Infinity]) {
  assert.throws(() => calculateInvoiceSubtotal([{ unitPrice, quantity: 1 }]), TypeError);
}
for (const quantity of ['1', null, 1.5, NaN, Infinity]) {
  assert.throws(() => calculateInvoiceSubtotal([{ unitPrice: 1, quantity }]), TypeError);
}
assert.throws(() => calculateInvoiceSubtotal([{ unitPrice: -0.01, quantity: 1 }]), RangeError);
assert.throws(() => calculateInvoiceSubtotal([{ unitPrice: 1, quantity: -1 }]), RangeError);
assert.throws(() => calculateInvoiceSubtotal([
  { unitPrice: Number.MAX_VALUE, quantity: 2 }
]), RangeError);

const stable = [{ unitPrice: 4, quantity: 2 }];
assert.throws(() => calculateInvoiceSubtotal([
  ...stable,
  { unitPrice: -1, quantity: 1 }
]), RangeError);
assert.deepEqual(stable, [{ unitPrice: 4, quantity: 2 }]);

